 JSONObject request(String route)throws Exception{return request(route,false);}
 JSONObject request(String route,boolean redirect)throws Exception{String key=key();if(key==null||key.isEmpty())throw new IOException("RawCast API key required. Add your own key in Settings → RawCast API.");HttpURLConnection connection=(HttpURLConnection)new URL("https://api.rawcast.space/v1"+route).openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("X-API-Key",key);connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("User-Agent","ZeroPlay/"+BuildConfig.VERSION_NAME);try{int code=connection.getResponseCode();if(!java.util.Objects.equals(key,key()))throw new IOException("RawCast configuration changed. Try again.");String limit=connection.getHeaderField("X-RateLimit-Limit"),remaining=connection.getHeaderField("X-RateLimit-Remaining");if(limit!=null&&remaining!=null)try{JSONObject value=new JSONObject().put("limit",Long.parseLong(limit)).put("remaining",Long.parseLong(remaining)).put("used",Math.max(0,Long.parseLong(limit)-Long.parseLong(remaining))).put("at",System.currentTimeMillis());String reset=connection.getHeaderField("X-RateLimit-Reset");if(reset!=null)value.put("reset",Long.parseLong(reset)*1000);usage=value;prefs.edit().putString("usage",value.toString()).apply();}catch(Exception ignored){}if(redirect&&Arrays.asList(301,302,303,307,308).contains(code))return new JSONObject().put("url",connection.getHeaderField("Location")).put("format","mp4");if(code!=200)throw new IOException(code==401?"RawCast API key rejected.":code==403?"RawCast key unavailable; check account verification.":code==404?"Unavailable for Download.":code==429?"RawCast rate or monthly quota limit reached.":"RawCast request failed. Try again later.");try(InputStream input=connection.getInputStream()){try{return new JSONObject(Catalog.read(input,2_000_000));}catch(JSONException error){throw new IOException("RawCast returned an unreadable response.");}}}finally{connection.disconnect();}}
 JSONObject resolve(String type,String id,int season,int episode,boolean fresh)throws Exception{if(!id.matches("[1-9][0-9]*")||!Arrays.asList("movie","tv").contains(type)||season<0||episode<1)throw new IOException("Select a valid title and episode.");String identity=type+":"+id+":"+season+":"+episode;if(!fresh&&(expiry.containsKey(identity)?expiry.get(identity):0L)>System.currentTimeMillis())return cache.get(identity);int epoch=generation;String pendingId=epoch+":"+identity;java.util.concurrent.FutureTask<JSONObject> task=new java.util.concurrent.FutureTask<>(()->{JSONObject value=request("/download/"+type+"/"+id+(type.equals("tv")?"/"+season+"/"+episode:"")+"?quality=1080p",true);if(value.has("tmdbId")&&!id.equals(value.optString("tmdbId"))||value.optString("title",value.optString("filename")).toLowerCase(Locale.ROOT).matches(".*(rick.?roll|never.gonna.give.you.up).*"))throw new IOException("RawCast returned the wrong download.");String address=value.optString("downloadUrl",value.optString("url"));URI uri=new URI(address);if(!Arrays.asList("","mp4").contains(value.optString("format").toLowerCase(Locale.ROOT))||!"https".equals(uri.getScheme())||uri.getUserInfo()!=null||address.contains(".m3u8"))throw new IOException("Unavailable for Download.");if(epoch!=generation)throw new IOException("RawCast configuration changed. Try again.");JSONObject result=new JSONObject().put("url",address);cache.put(identity,result);expiry.put(identity,System.currentTimeMillis()+120000);return result;});java.util.concurrent.FutureTask<JSONObject> existing=pending.putIfAbsent(pendingId,task);try{if(existing==null){task.run();return task.get();}return existing.get();}catch(java.util.concurrent.ExecutionException error){Throwable cause=error.getCause();if(cause instanceof Exception)throw (Exception)cause;throw new IOException("RawCast request failed.");}finally{pending.remove(pendingId,task);}}

 JSONObject manifest(String address,JSONObject headers)throws Exception{for(int i=0;i<6;i++){URL url=new URL(address);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null)throw new IOException("Invalid manifest");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);Iterator<String> names=headers.keys();while(names.hasNext()){String name=names.next();c.setRequestProperty(name,headers.getString(name));}if(Arrays.asList("rawcast.space","api.rawcast.space").contains(url.getHost()))c.setRequestProperty("X-API-Key",key());try{int status=c.getResponseCode();if(Arrays.asList(301,302,303,307,308).contains(status)){String next=c.getHeaderField("Location");if(next==null)throw new IOException("Invalid redirect");address=new URL(url,next).toString();continue;}if(status!=200)throw new IOException("Unavailable manifest");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream input=c.getInputStream()){byte[] buffer=new byte[8192];while(out.size()<65536){int n=input.read(buffer);if(n<0)break;out.write(buffer,0,n);String prefix=out.toString("UTF-8");if(prefix.contains("<MPD")||prefix.contains("#EXTM3U"))break;}}String text=out.toString("UTF-8");if(text.toLowerCase(Locale.ROOT).matches("(?s).*(rick.?roll|dqw4w9wgxc|never.gonna.give.you.up).*"))throw new IOException("Wrong video");String mime=text.contains("<MPD")?"application/dash+xml":text.contains("#EXTM3U")?"application/x-mpegURL":null;if(mime==null)throw new IOException("Not an adaptive manifest");return new JSONObject().put("url",address).put("mimeType",mime);}finally{c.disconnect();}}throw new IOException("Too many redirects");}
 JSONObject stream(String type,String id,int season,int episode)throws Exception{
  if(!id.matches("[1-9][0-9]*")||!Arrays.asList("movie","tv").contains(type)||season<1||episode<1)throw new IOException("Invalid playback title or episode.");String route="/sources/"+type+"/"+id+(type.equals("tv")?"/"+season+"/"+episode:"")+"?lang=en&cleanOnly=true",identity="stream:"+route;int epoch=generation;if((expiry.containsKey(identity)?expiry.get(identity):0L)>System.currentTimeMillis())return cache.get(identity);JSONObject data=request(route);if(data.has("tmdbId")&&!id.equals(data.optString("tmdbId"))||data.has("mediaType")&&!type.equals(data.optString("mediaType")))throw new IOException("RawCast returned the wrong title. Choose another source.");JSONArray servers=data.optJSONArray("servers");if(servers!=null)for(int i=0;i<servers.length();i++){JSONObject server=servers.optJSONObject(i);JSONArray streams=server==null?null:server.optJSONArray("streams");if(streams==null)continue;for(int n=0;n<streams.length();n++){JSONObject row=streams.optJSONObject(n);if(row==null||server.optString("format").equals("mp4"))continue;try{String address=row.optString("manifestUrl");if(address.isEmpty()){URI resolver=new URI(row.optString("url"));if(!"https".equals(resolver.getScheme())||!Arrays.asList("api.rawcast.space","rawcast.space").contains(resolver.getHost())||!resolver.getPath().startsWith("/v1/resolve/"))continue;JSONObject resolved=request(resolver.getRawPath().substring(3)+(resolver.getRawQuery()==null?"":"?"+resolver.getRawQuery()),true);address=resolved.optString("manifestUrl",resolved.optString("url"));}URI uri=new URI(address);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||address.toLowerCase(Locale.ROOT).matches(".*(rick.?roll|dqw4w9wgxc|never.gonna.give.you.up).*"))continue;if(epoch!=generation)throw new IOException("RawCast configuration changed. Try again.");JSONObject headers=new JSONObject(),provided=row.optJSONObject("headers");if(provided!=null){Iterator<String> names=provided.keys();while(names.hasNext()){String name=names.next(),value=provided.optString(name);if(Arrays.asList("referer","user-agent","origin").contains(name.toLowerCase(Locale.ROOT))&&!value.contains("\r")&&!value.contains("\n"))headers.put(name,value);}}JSONObject checked=manifest(address,headers);if(epoch!=generation)throw new IOException("RawCast configuration changed. Try again.");JSONObject source=checked.put("headers",headers);JSONArray subs=data.optJSONArray("subtitles");if(subs!=null)source.put("subtitles",subs);cache.put(identity,source);expiry.put(identity,System.currentTimeMillis()+120000);return source;}catch(Exception error){if(epoch!=generation)throw error;}}}throw new IOException("RawCast stream unavailable. Choose another source.");}
 void test()throws Exception{request("/meta/movie/550?lang=en-US");}void refreshUsage()throws Exception{request("/meta/movie/550?lang=en-US");}
